#!/usr/bin/env python3
"""Parse the five saved FO tables and reproduce the conditional branching comparison.

Default execution is offline. --requery-fo requests the same five fixed physical
points once each and saves a separate replay; it is never needed for offline
verification. No lifetime unit or experimental B value is inferred here.
"""
from __future__ import annotations

import argparse
import datetime as dt
import hashlib
import json
import re
from decimal import Decimal, getcontext
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlencode
from urllib.request import Request, urlopen

getcontext().prec = 30
HERE = Path(__file__).resolve().parent
URL = "https://bricc.anu.edu.au/"
CASES = (
    ("B1-I18-401p2", "401.2", "M1", "probe-fo-401p2-M1"),
    ("B1-I18-389p6", "389.6", "M1", "query-02-389p6-M1"),
    ("B1-I18-757p4", "757.4", "E2", "query-03-757p4-E2"),
    ("B2-I15-199p6", "199.6", "M1", "query-04-199p6-M1"),
    ("B2-I15-382p0", "382.0", "E2", "query-05-382p0-E2"),
)
MOTHERS = {
    "B1-I18": {"tau_given": "0.56", "branches": (("B1-I18-401p2", "0.57"), ("B1-I18-757p4", "0.24"), ("B1-I18-389p6", "0.19"))},
    "B2-I15": {"tau_given": "1.27", "branches": (("B2-I15-199p6", "0.93"), ("B2-I15-382p0", "0.07"))},
}


class Tables(HTMLParser):
    def __init__(self):
        super().__init__()
        self.skip = 0
        self.incell = False
        self.cell = []
        self.row = []
        self.rows = []
        self.text = []

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
        if tag == "tr":
            self.row = []
        if tag in ("td", "th"):
            self.incell, self.cell = True, []

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            self.skip = max(0, self.skip - 1)
        if tag in ("td", "th"):
            self.incell = False
            self.row.append(" ".join(self.cell))
        if tag == "tr" and self.row:
            self.rows.append(self.row)

    def handle_data(self, data):
        if not self.skip and data.strip():
            self.text.append(data.strip())
            if self.incell:
                self.cell.append(data.strip())


def nds_value(parts):
    text = " ".join(parts).strip()
    if not text:
        return {"reported": "", "value": None, "uncertainty_abs": None}
    match = re.fullmatch(r"([0-9]+(?:\.[0-9]+)?(?:E[+-]?[0-9]+)?)\s*(?:\(([0-9]+)\))?", text, re.I)
    if not match:
        raise ValueError(f"unsupported ICC value: {text}")
    value = Decimal(match[1])
    uncertainty = Decimal(match[2]) * Decimal(10) ** value.as_tuple().exponent if match[2] else None
    return {"reported": text, "value": str(value), "uncertainty_abs": str(uncertainty) if uncertainty is not None else None}


def parse_case(case, folder=HERE):
    case_id, energy, multipole, stem = case
    path = folder / (stem + ".html")
    body = path.read_bytes()
    parser = Tables()
    parser.feed(body.decode("utf-8"))
    text = "\n".join(parser.text)
    version = next((row[0] for row in parser.rows if row and row[0].startswith("BrIccS v")), None)
    if not version or not re.search(r"Z=60\b", text) or not re.search(r"Data Sets:\s*BrIccFO\b", text):
        raise ValueError(f"missing version/Z/table identity: {path}")
    returned_energy = re.search(r"γ-energy:\s*([0-9.]+)\s*keV", text)
    if not returned_energy or Decimal(returned_energy[1]) != Decimal(energy):
        raise ValueError(f"energy identity mismatch: {path}")
    if ["Shell", "E(ce)", multipole] not in parser.rows:
        raise ValueError(f"multipolarity identity mismatch: {path}")
    shells = {}
    for row in parser.rows:
        if len(row) >= 3 and re.fullmatch(r"Tot|K|[LMNOPQ](?:[1-9]|-tot)", row[0]):
            shells[row[0]] = {"electron_energy_keV": row[1] or None, **nds_value(row[2:])}
    if "Tot" not in shells or shells["Tot"]["value"] is None or "K" not in shells:
        raise ValueError(f"no usable reported total/K coefficient: {path}")
    warnings = [line for line in parser.text if "could not" in line]
    missing = [name for name, record in shells.items() if record["value"] is None]
    major_names = [name for name in shells if name == "K" or name.endswith("-tot")]
    major_sum = sum(Decimal(shells[name]["value"]) for name in major_names if shells[name]["value"] is not None)
    total = Decimal(shells["Tot"]["value"])
    assert total >= Decimal(shells["K"]["value"]) > 0
    rounding_residual = total - major_sum
    assert abs(rounding_residual) <= Decimal(shells["Tot"]["uncertainty_abs"])
    return {"id": case_id, "Z": 60, "energy_keV": energy, "pure_multipolarity_assumption": multipole,
            "dataset": "BrIccFO", "backend_version": version,
            "alpha_T_reported": shells["Tot"], "alpha_K": shells["K"], "subshells_and_major_sums": shells,
            "warnings": warnings, "unavailable_subshell_rows": missing,
            "shell_complete_in_returned_table": not (warnings or missing),
            "status": "reported-total-with-coverage-warning" if warnings or missing else "reported-total-no-coverage-warning",
            "major_shell_sum": str(major_sum), "reported_total_minus_major_sum": str(rounding_residual),
            "html_path": str(path), "html_sha256": hashlib.sha256(body).hexdigest()}


def compare(lookups):
    by_id = {record["id"]: record for record in lookups}
    comparisons = {}
    for mother, control in MOTHERS.items():
        branches = [(by_id[key], Decimal(fraction)) for key, fraction in control["branches"]]
        assert sum(fraction for _, fraction in branches) == 1
        denominator = sum(fraction * (1 + Decimal(record["alpha_T_reported"]["value"])) for record, fraction in branches)
        rows = []
        for record, fraction in branches:
            alpha = Decimal(record["alpha_T_reported"]["value"])
            photon = fraction / denominator
            total = fraction / (1 + alpha)
            ratio = photon / total
            rows.append({"lookup_id": record["id"], "fraction_as_given": str(fraction),
                         "tau_times_gamma_rate_if_photon_fraction": str(photon),
                         "tau_times_gamma_rate_if_total_fraction": str(total),
                         "photon_formula_over_total_formula": str(ratio), "difference_percent": str(100 * (ratio - 1)),
                         "ICC_coverage_status": record["status"]})
        comparisons[mother] = {"tau_given": control["tau_given"],
                               "rate_output_convention": "dimensionless tau*T_gamma; no lifetime-unit conversion",
                               "D_photon": str(denominator), "rows": rows,
                               "coverage_warning_in_any_branch": any(record["warnings"] for record, _ in branches),
                               "interpretation": "conditional modern-FO forward comparison, not MU08 method identification or an experimental fit"}
    return comparisons


def replay_queries():
    folder = HERE / ("replay-" + dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ"))
    folder.mkdir(exist_ok=False)
    for case_id, energy, multipole, stem in CASES:
        params = {"atomic": "60", "energy": energy, "eerror": "", "multipole": multipole,
                  "delta": "", "derror": "", "subshells": "on", "dataset": "BrIccFO", "calculate": "Calculate"}
        (folder / (stem + "-request.json")).write_text(json.dumps({"url": URL, "params": params, "retries": 0}, indent=2) + "\n")
        try:
            with urlopen(Request(URL, data=urlencode(params).encode(), headers={"User-Agent": "Mozilla/5.0", "Content-Type": "application/x-www-form-urlencoded"}), timeout=30) as response:
                body = response.read(2_000_001)
            if len(body) > 2_000_000:
                raise ValueError("bounded response limit exceeded")
            (folder / (stem + ".html")).write_bytes(body)
        except Exception as exc:
            (folder / (stem + "-failure.json")).write_text(json.dumps({"error": str(exc)}, indent=2) + "\n")
    return folder


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--requery-fo", action="store_true", help="opt in to a separate five-point FO replay; default is offline")
    args = parser.parse_args()
    folder = replay_queries() if args.requery_fo else HERE
    lookups = [parse_case(case, folder) for case in CASES]
    result = {"status": "five-reported-FO-totals; two-have-N6-coverage-warning", "lookups": lookups,
              "forward_comparison": compare(lookups), "lookup_replay_performed": args.requery_fo,
              "new_queries_in_this_execution": 5 if args.requery_fo else 0}
    (folder / "parsed-results-and-forward.json").write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n")
    print(json.dumps({"status": result["status"], "new_queries": result["new_queries_in_this_execution"]}, ensure_ascii=False))
    for record in lookups:
        print(record["id"], record["alpha_T_reported"], record["status"])
    for mother, comparison in result["forward_comparison"].items():
        print(mother, "D=", comparison["D_photon"])
        for row in comparison["rows"]:
            print(row["lookup_id"], "photon-vs-total difference%", row["difference_percent"])


if __name__ == "__main__":
    main()
